<script setup lang="ts">
import { computed } from 'vue';
import WdCategoryIcon from '@components/categories/WdCategoryIcon.vue';
import { useI18n } from 'vue-i18n';
import WdDayLabel from '@components/content/place/WdDayLabel.vue';

const { t } = useI18n();

type OccupancyStatus = 'empty' | 'low' | 'medium' | 'high' | 'full' | 'free_unknown' | 'unknown';

interface AvailabilityDay {
  date: string;
  reservation_status: string;
  free?: number | null;
  total?: number | null;
  occupancy_percent?: number | null;
  occupancy_steps?: number | null;
  occupancy_status: OccupancyStatus;
  hut_type: string;
  type_slug?: string | null;
  type_color?: string | null;
  link: string;
  loading?: boolean;
}

interface Props {
  day: AvailabilityDay;
  /** Maps occupancy_status slug → SVG URL */
  availabilityIcons: Record<string, string>;
  isSelected?: boolean;
  hutTypeColor?: string;
  /** Map of type_slug → icon URL for hut type icons */
  hutTypeIcons?: Record<string, string>;
  /** Whether this day is in the past */
  isPast?: boolean;
}

const props = withDefaults(defineProps<Props>(), {
  isSelected: false,
  hutTypeColor: undefined,
  hutTypeIcons: () => ({}),
  isPast: false,
});

const isLoading = computed(() => props.day.loading === true);
const isUnknown = computed(
  () =>
    props.day.reservation_status === 'unknown' ||
    (props.day.free === 0 && props.day.total === 0 && !isLoading.value)
);

/** Free beds confirmed, but count not published by the source */
const isFreeUnknown = computed(
  () =>
    !isUnknown.value && (props.day.occupancy_status === 'free_unknown' || props.day.free == null)
);

const iconUrl = computed(() => {
  const status = props.day.occupancy_status;
  if (props.availabilityIcons[status]) {
    return props.availabilityIcons[status];
  }
  // Fallback until a dedicated free_unknown icon exists on the backend
  if (isFreeUnknown.value) {
    return props.availabilityIcons['medium'] ?? props.availabilityIcons['unknown'] ?? null;
  }
  return props.availabilityIcons['unknown'] ?? null;
});

/** Occupancy status display name */
const statusLabel = computed(() => {
  if (isLoading.value) return '';
  // t() inside the computed keeps the label reactive to language switches
  const map: Record<string, string> = {
    empty: t('availability.status.empty'),
    low: t('availability.status.low'),
    medium: t('availability.status.medium'),
    high: t('availability.status.high'),
    full: t('availability.status.full'),
    free_unknown: t('availability.status.free_unknown'),
    unknown: t('availability.status.unknown'),
  };
  return map[props.day.occupancy_status] ?? '';
});

/** Free count for display: '?' if not published by the source (free_unknown) */
const freeLabel = computed(() =>
  props.day.free == null || isUnknown.value ? '?' : String(props.day.free)
);

/** Total for display: '?' if not published by the source */
const totalLabel = computed(() =>
  props.day.total == null || isUnknown.value ? '?' : String(props.day.total)
);

/** Badge style: saturated chip in the hut type color. The color is exposed
 * as a custom property — the CSS derives a light-mode-deepened background
 * via color-mix so white content stays readable in both modes. */
const badgeStyle = computed(() => {
  if (!props.hutTypeColor) return undefined;
  return { '--badge-color': props.hutTypeColor };
});

// Full date for tooltip
const fullDate = computed(() => {
  const d = new Date(`${props.day.date}T00:00:00`);
  return d.toLocaleDateString('de-CH', {
    weekday: 'long',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  });
});

const tooltipLines = computed(() => {
  const lines: string[] = [fullDate.value];
  if (isUnknown.value) {
    lines.push(t('availability.no_data'));
  } else if (!isLoading.value) {
    lines.push(
      `${freeLabel.value} ${t('availability.free')} / ${totalLabel.value} ${t('availability.total')}`
    );
  }
  if (props.day.hut_type && props.day.hut_type !== 'unknown') {
    lines.push(props.day.hut_type);
  }
  return lines;
});
</script>

<template>
  <a
    :href="day.link"
    target="_blank"
    rel="noopener noreferrer"
    draggable="false"
    class="wd-accommodation-day column items-center"
    :class="{
      'wd-accommodation-day--selected': isSelected,
      'wd-accommodation-day--past': isPast,
    }"
  >
    <!-- Day name -->
    <WdDayLabel :date="day.date" :is-active="isSelected" />

    <!-- Availability icon + free number on one line -->
    <div class="wd-accommodation-day__main">
      <template v-if="isLoading">
        <q-skeleton type="circle" width="16px" height="16px" />
        <q-skeleton type="text" width="20px" height="14px" />
      </template>
      <template v-else>
        <div class="wd-accommodation-day__avail-icon">
          <img
            v-if="iconUrl"
            :src="iconUrl"
            width="16"
            height="16"
            style="object-fit: contain"
            loading="eager"
          />
        </div>
        <span
          v-if="!isUnknown"
          class="wd-accommodation-day__free"
          :class="'wd-occ-' + day.occupancy_status"
        >
          {{ freeLabel }}
        </span>
      </template>
    </div>

    <!-- Occupancy status label -->
    <div
      v-if="statusLabel"
      class="wd-accommodation-day__status"
      :class="[
        { 'wd-accommodation-day__status--small': statusLabel.length > 5 },
        'wd-occ-' + (isUnknown ? 'unknown' : day.occupancy_status),
      ]"
    >
      {{ statusLabel }}
    </div>

    <!-- Total badge at bottom -->
    <div class="wd-accommodation-day__badge-row">
      <template v-if="isLoading">
        <q-skeleton type="text" width="40px" height="14px" />
      </template>
      <div
        v-else-if="(day.total ?? 0) > 0 && hutTypeColor"
        class="wd-accommodation-day__badge"
        :style="badgeStyle"
      >
        <WdCategoryIcon
          v-if="day.type_slug"
          :identifier="'accommodation.' + day.type_slug"
          :href="day.type_slug ? hutTypeIcons[day.type_slug] : undefined"
          variant="mono"
          :size="14"
          color="rgba(255,255,255,0.92)"
          style="flex-shrink: 0"
        />
        <span class="wd-accommodation-day__badge-total">{{ day.total }}</span>
      </div>
      <!-- Unknown or missing total: show ? in same space, no badge -->
      <span v-else-if="isUnknown || day.total == null" class="wd-accommodation-day__badge-unknown"
        >?</span
      >
    </div>

    <!-- Tooltip -->
    <q-tooltip :delay="700">
      <div v-for="(line, i) in tooltipLines" :key="i">{{ line }}</div>
    </q-tooltip>
  </a>
</template>

